function token():string{if(empty($_SESSION['ferrn_csrf']))$_SESSION['ferrn_csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['ferrn_csrf'];}
function check_token():void{$t=(string)($_POST['csrf']??'');if(!$t||!hash_equals((string)($_SESSION['ferrn_csrf']??''),$t)){http_response_code(403);exit('Invalid CSRF token');}}
function logged():bool{return !empty($_SESSION['ferrn_admin']);}
function go(string $q=''):never{header('Location: /studio/'.($q?'?'.$q:''));exit;}
$error='';
if(isset($_GET['logout'])){session_destroy();go();}
if(!logged()&&$_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='login'){$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if($email===strtolower(FERRN_ADMIN_EMAIL)&&password_verify($pw,FERRN_ADMIN_HASH)){session_regenerate_id(true);$_SESSION['ferrn_admin']=true;token();go();}$error='That login did not match.';}
if(logged()&&$_SERVER['REQUEST_METHOD']==='POST'){check_token();$action=(string)($_POST['action']??'');if($action==='save_post'){$posts=ferrn_posts();$id=trim((string)($_POST['id']??''));$title=trim((string)($_POST['title']??''));$slug=ferrn_slugify((string)($_POST['slug']?:$title));$category=trim((string)($_POST['category']??'Insight'))?:'Insight';$excerpt=trim((string)($_POST['excerpt']??''));$content=ferrn_sanitize_html((string)($_POST['content']??''));$status=($_POST['status']??'draft')==='published'?'published':'draft';if($title===''||trim(strip_tags($content))===''){$error='A title and article body are required.';}else{$now=date(DATE_ATOM);$found=false;foreach($posts as &$p){if(($p['id']??'')===$id&&$id!==''){$found=true;$was=$p['status']??'draft';$p=array_merge($p,['title'=>$title,'slug'=>$slug,'category'=>$category,'excerpt'=>$excerpt?:ferrn_excerpt($content),'content'=>$content,'status'=>$status,'updated_at'=>$now]);if($status==='published'&&($was!=='published'||empty($p['published_at'])))$p['published_at']=$now;break;}}unset($p);if(!$found)$posts[]=['id'=>bin2hex(random_bytes(6)),'title'=>$title,'slug'=>$slug,'category'=>$category,'excerpt'=>$excerpt?:ferrn_excerpt($content),'content'=>$content,'status'=>$status,'created_at'=>$now,'updated_at'=>$now,'published_at'=>$status==='published'?$now:null];ferrn_save_json('posts.json',$posts);go('tab=posts&saved=1');}}
elseif($action==='delete_post'){$id=(string)($_POST['id']??'');ferrn_save_json('posts.json',array_values(array_filter(ferrn_posts(),fn($p)=>($p['id']??'')!==$id)));go('tab=posts');}
elseif($action==='lead_status'){$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'new');$allowed=['new','contacted','qualified','proposal','won','lost'];if(!in_array($status,$allowed,true))$status='new';$leads=ferrn_leads();foreach($leads as &$l)if(($l['id']??'')===$id)$l['status']=$status;unset($l);ferrn_save_json('leads.json',$leads);go('tab=leads');}
elseif($action==='delete_lead'){$id=(string)($_POST['id']??'');ferrn_save_json('leads.json',array_values(array_filter(ferrn_leads(),fn($l)=>($l['id']??'')!==$id)));go('tab=leads');}}
if(!logged()):?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ferrn Studio</title><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;place-items:center;background:#0a0a0a;color:#f5f5f2;font-family:Poppins,Arial;padding:20px}.card{width:min(450px,100%);border:1px solid #2a2a2a;background:#111;border-radius:22px;padding:34px}.mark{width:48px;height:48px;margin-bottom:34px}h1{font-size:34px;letter-spacing:-.05em;margin:0 0 8px}p{color:#888;font-size:13px;line-height:1.6;margin:0 0 28px}.field{margin-top:14px}label{display:block;font-size:11px;color:#8c8c88;margin-bottom:7px}input{width:100%;border:1px solid #292929;background:#090909;color:#fff;border-radius:12px;padding:14px 15px;outline:none}input:focus{border-color:#ff4100}button{margin-top:18px;width:100%;height:50px;border:0;border-radius:999px;background:#ff4100;color:white;font-weight:600}.err{color:#ff9b82;background:#28130d;border:1px solid #63230f;padding:10px;border-radius:10px;font-size:12px;margin-bottom:14px}</style></head><body><form class="card" method="post"><img class="mark" src="/assets/ferrn-mark.svg" alt="Ferrn"><h1>Ferrn Studio</h1><p>Private content and enquiry dashboard.</p><?php if($error):?><div class="err"><?=htmlspecialchars($error)?></div><?php endif;?><input type="hidden" name="action" value="login"><div class="field"><label>Email</label><input name="email" type="email" required value="michael@ferrnagency.com" autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button type="submit">Sign in</button></form></body></html><?php exit;endif;
