?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ferrn Studio</title><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap" rel="stylesheet"><style>:root{--o:#ff4100}*{box-sizing:border-box}body{margin:0;background:#0a0a0a;color:#f6f6f2;font-family:Poppins,Arial}.shell{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{border-right:1px solid #252525;padding:24px 18px;position:sticky;top:0;height:100vh}.mark{width:38px;margin:3px 8px 38px}.side a{display:block;padding:11px 12px;border-radius:10px;color:#8f8f8a;font-size:13px;margin:3px 0}.side a.active,.side a:hover{background:#171717;color:#fff}.logout{position:absolute;bottom:24px;left:18px;right:18px}.main{padding:34px clamp(20px,4vw,64px);max-width:1500px;width:100%}.top{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:30px}.top h1{font-size:38px;letter-spacing:-.05em;margin:0}.muted{color:#7d7d79}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat,.panel,.lead-card{border:1px solid #252525;background:#111;border-radius:16px}.stat{padding:20px}.stat small{color:#777}.stat strong{display:block;font-size:30px;margin-top:10px}.panel{padding:22px;margin-top:18px}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:20px}.panel h2{font-size:20px;margin:0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:span 2}.field label{font-size:10px;color:#888}.field input,.field textarea,.field select,select{border:1px solid #292929;background:#090909;color:#fff;border-radius:10px;padding:12px;outline:none}.field textarea{min-height:310px;resize:vertical;font-family:ui-monospace,monospace}.primary,.smallbtn{border:0;border-radius:999px;background:var(--o);color:#fff;padding:11px 15px;font-size:11px;font-weight:600;text-decoration:none;cursor:pointer}.smallbtn.secondary{background:#1a1a1a;border:1px solid #303030}.smallbtn.danger{background:#32120b;color:#ff9c83;border:1px solid #64220f}.form-actions,.actions,.lead-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:16px}.table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{text-align:left;padding:13px 8px;border-top:1px solid #242424;vertical-align:top}.table th{color:#777;font-weight:500}.status{display:inline-flex;padding:6px 9px;border-radius:999px;background:#191919;border:1px solid #2e2e2e;color:#aaa;font-size:10px}.lead-card{padding:20px;margin-top:12px}.lead-top{display:flex;justify-content:space-between;gap:20px}.lead-card h3{margin:0 0 6px}.lead-meta{display:flex;gap:12px;flex-wrap:wrap;color:#777;font-size:10px}.lead-card p{color:#aaa;font-size:13px;line-height:1.7}.empty{padding:30px;text-align:center;color:#777}.flash{padding:10px 12px;border:1px solid #245433;background:#102318;color:#8ee4a4;border-radius:10px;font-size:12px;margin-bottom:14px}@media(max-width:800px){.shell{grid-template-columns:1fr}.side{height:auto;position:static;display:flex;gap:5px;align-items:center;overflow:auto;border-right:0;border-bottom:1px solid #252525}.mark{width:30px;margin:0 12px 0 0}.side a{white-space:nowrap}.logout{position:static;margin-left:auto}.stats{grid-template-columns:1fr 1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.table{display:block;overflow:auto}}</style></head><body><div class="shell"><aside class="side"><img class="mark" src="/assets/ferrn-mark.svg" alt="Ferrn"><a class="<?=$tab==='dashboard'?'active':''?>" href="/studio/">Dashboard</a><a class="<?=$tab==='posts'?'active':''?>" href="?tab=posts">Posts</a><a class="<?=$tab==='leads'?'active':''?>" href="?tab=leads">Leads</a><a class="logout" href="?logout=1">Sign out</a></aside><main class="main"><div class="top"><div><div class="muted" style="font-size:11px;text-transform:uppercase;letter-spacing:.12em">Ferrn Studio</div><h1><?=ucfirst(htmlspecialchars($tab))?></h1></div><a class="smallbtn secondary" href="/" target="_blank">View website ↗</a></div>
<?php if($tab==='dashboard'):?><div class="stats"><div class="stat"><small>Published posts</small><strong><?=count(array_filter($posts,fn($p)=>($p['status']??'')==='published'))?></strong></div><div class="stat"><small>New leads</small><strong><?=$counts['new']?></strong></div><div class="stat"><small>Qualified</small><strong><?=$counts['qualified']?></strong></div><div class="stat"><small>Won</small><strong><?=$counts['won']?></strong></div></div><section class="panel"><div class="panel-head"><h2>Pipeline</h2><a class="smallbtn secondary" href="?tab=leads">Open leads</a></div><div class="stats"><?php foreach(['contacted','qualified','proposal','won'] as $s):?><div class="stat"><small><?=ucfirst($s)?></small><strong><?=$counts[$s]?></strong></div><?php endforeach;?></div></section>
<?php elseif($tab==='posts'):?><section class="panel"><div class="panel-head"><h2><?=$edit?'Edit article':'New article'?></h2><?php if($edit):?><a class="smallbtn secondary" href="?tab=posts">Cancel edit</a><?php endif;?></div><?php if(isset($_GET['saved'])):?><div class="flash">Article saved.</div><?php endif;?><?php if($error):?><div class="flash" style="background:#32110a;border-color:#6a2414;color:#ff9c83"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(token())?>"><input type="hidden" name="action" value="save_post"><input type="hidden" name="id" value="<?=htmlspecialchars($edit['id']??'')?>"><div class="form-grid"><div class="field"><label>Title</label><input name="title" required value="<?=htmlspecialchars($edit['title']??'')?>"></div><div class="field"><label>Slug</label><input name="slug" value="<?=htmlspecialchars($edit['slug']??'')?>" placeholder="auto-generated-from-title"></div><div class="field"><label>Category</label><input name="category" value="<?=htmlspecialchars($edit['category']??'Strategy')?>"></div><div class="field"><label>Status</label><select name="status"><option value="draft" <?=($edit['status']??'')!=='published'?'selected':''?>>Draft</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Published</option></select></div><div class="field full"><label>SEO excerpt / summary</label><textarea name="excerpt" style="min-height:90px;font-family:Poppins,Arial"><?=htmlspecialchars($edit['excerpt']??'')?></textarea></div><div class="field full"><label>Article body (safe HTML supported)</label><textarea name="content" required placeholder="<p>Start writing…</p>"><?=htmlspecialchars($edit['content']??'')?></textarea></div></div><div class="form-actions"><button class="primary" type="submit">Save article</button><?php if($edit&&($edit['status']??'')==='published'):?><a class="smallbtn secondary" target="_blank" href="/insights/<?=htmlspecialchars($edit['slug'])?>">View live ↗</a><?php endif;?></div></form></section><section class="panel"><div class="panel-head"><h2>All posts</h2><span class="muted"><?=count($posts)?> total</span></div><table class="table"><thead><tr><th>Article</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><strong><?=htmlspecialchars($p['title']??'')?></strong><div class="muted"><?=htmlspecialchars($p['category']??'')?></div></td><td><span class="status"><?=htmlspecialchars($p['status']??'draft')?></span></td><td class="muted"><?=!empty($p['updated_at'])?htmlspecialchars(date('M j, Y',strtotime($p['updated_at']))):''?></td><td><div class="actions"><a class="smallbtn secondary" href="?tab=posts&edit=<?=urlencode($p['id']??'')?>">Edit</a><form method="post" onsubmit="return confirm('Delete this article?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars(token())?>"><input type="hidden" name="action" value="delete_post"><input type="hidden" name="id" value="<?=htmlspecialchars($p['id']??'')?>"><button class="smallbtn danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></section>
<?php elseif($tab==='leads'):?><section class="panel"><div class="panel-head"><h2>Website enquiries</h2><span class="muted"><?=count($leads)?> total</span></div><?php foreach(array_reverse($leads) as $l):?><div class="lead-card"><div class="lead-top"><div><h3><?=htmlspecialchars($l['name']??'')?></h3><div class="lead-meta"><a href="mailto:<?=htmlspecialchars($l['email']??'')?>"><?=htmlspecialchars($l['email']??'')?></a><?php foreach(['company','project','budget','timeline'] as $k)if(!empty($l[$k])):?><span><?=htmlspecialchars($l[$k])?></span><?php endif;?><span><?=!empty($l['created_at'])?htmlspecialchars(date('M j, Y g:ia',strtotime($l['created_at']))):''?></span></div></div><span class="status"><?=htmlspecialchars($l['status']??'new')?></span></div><p><?=nl2br(htmlspecialchars($l['message']??''))?></p><div class="lead-actions"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(token())?>"><input type="hidden" name="action" value="lead_status"><input type="hidden" name="id" value="<?=htmlspecialchars($l['id']??'')?>"><select name="status" onchange="this.form.submit()"><?php foreach(['new','contacted','qualified','proposal','won','lost'] as $s):?><option value="<?=$s?>" <?=($l['status']??'new')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></form><a class="smallbtn secondary" href="mailto:<?=htmlspecialchars($l['email']??'')?>?subject=Re:%20your%20Ferrn%20project%20inquiry">Reply</a><form method="post" onsubmit="return confirm('Delete this lead?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars(token())?>"><input type="hidden" name="action" value="delete_lead"><input type="hidden" name="id" value="<?=htmlspecialchars($l['id']??'')?>"><button class="smallbtn danger" type="submit">Delete</button></form></div></div><?php endforeach;?><?php if(!$leads):?><div class="empty">No enquiries yet. Website form submissions will appear here.</div><?php endif;?></section><?php endif;?></main></div></body></html